def minPath(grid, k):
    n = len(grid)
    if k == 1:
        return [min(min(row) for row in grid)]

    # 记录每个值的位置
    pos = {}
    for i in range(n):
        for j in range(n):
            pos[grid[i][j]] = (i, j)

    # 从值1开始
    start_i, start_j = pos[1]

    # 动态规划：dp[length][cell] = 从该cell出发长度为length的最小路径（列表）
    # 但为了效率，我们只保留每个cell在特定长度下的最优路径
    # 由于k可能很大，我们使用迭代方法，从长度1开始逐步扩展

    # 初始化：长度为1的路径就是每个cell本身
    dp = {}
    for i in range(n):
        for j in range(n):
            dp[(i, j)] = [grid[i][j]]

    # 逐步扩展长度
    for length in range(2, k+1):
        new_dp = {}
        for i in range(n):
            for j in range(n):
                # 从当前cell出发，选择邻居中能产生最小路径的
                best_path = None
                for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ni, nj = i+di, j+dj
                    if 0 <= ni < n and 0 <= nj < n:
                        candidate = [grid[i][j]] + dp[(ni, nj)]
                        if best_path is None or candidate < best_path:
                            best_path = candidate
                new_dp[(i, j)] = best_path
        dp = new_dp

    # 最终答案：从任意cell出发长度为k的最小路径
    answer = None
    for i in range(n):
        for j in range(n):
            if answer is None or dp[(i, j)] < answer:
                answer = dp[(i, j)]
    return answer
